@@ -0,0 +1,312 @@
+/*
+  날짜·달 고르기가 함께 쓰는 생김새다.
+
+  브라우저가 내장한 달력 팝업은 CSS로 손댈 수 없다 — 크롬은 그 위젯을 페이지 바깥에서 그린다.
+  그래서 달력 아이콘을 감추고 같은 자리에 우리 버튼을 두어 Popover 를 연다. 입력칸 자체는
+  `type="date"`로 남겨 두어 타이핑·검증·자동완성이 그대로 동작한다.
+*/
+
+.wrap {
+  position: relative;
+  display: inline-flex;
+  align-items: center;
+}
+
+/*
+  아이콘이 앉을 자리만큼 오른쪽을 비운다. 나머지 생김새는 부르는 쪽이 넘긴 클래스가 정한다.
+
+  `.wrap`을 앞에 둬서 명시도를 0-2-0으로 올린다. 클래스 하나짜리로 두면 부르는 쪽의
+  `padding` 한 줄(예: AxisField 의 `.input`)과 명시도가 같아져 스타일시트가 끼워진 순서로
+  승부가 갈리고, 그때는 아이콘이 글자 위에 겹쳐 앉는다.
+*/
+.wrap .input {
+  padding-right: 32px;
+}
+
+.input::-webkit-calendar-picker-indicator {
+  -webkit-appearance: none;
+  display: none;
+}
+
+/* 파이어폭스는 지우기 단추를 따로 그린다. 우리 버튼과 겹치지 않게 같이 감춘다. */
+.input::-moz-calendar-picker-indicator {
+  display: none;
+}
+
+.trigger {
+  position: absolute;
+  right: 6px;
+  display: inline-grid;
+  place-items: center;
+  width: 22px;
+  height: 22px;
+  padding: 0;
+  border: 0;
+  border-radius: 6px;
+  background: transparent;
+  color: var(--thorp-copy);
+  cursor: pointer;
+  transition: color 0.14s ease, background-color 0.14s ease;
+}
+
+.trigger:hover:not(:disabled) {
+  background: var(--thorp-surface-raised);
+  color: var(--thorp-accent-soft);
+}
+
+.trigger:disabled {
+  opacity: 0.4;
+  cursor: not-allowed;
+}
+
+.trigger:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+/* 펼친 판. 층으로는 카드 위에 뜨므로 그림자와 테두리가 경계를 진다. */
+.panel {
+  z-index: 70;
+  width: 268px;
+  padding: 12px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 14px;
+  background: var(--thorp-surface-raised);
+  box-shadow: var(--thorp-shadow);
+  color: var(--thorp-foreground);
+}
+
+.head {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px;
+  margin-bottom: 10px;
+}
+
+.headLabel {
+  flex: 1;
+  padding: 4px 8px;
+  border: 1px solid transparent;
+  border-radius: 8px;
+  background: transparent;
+  color: inherit;
+  font: inherit;
+  font-size: 0.88rem;
+  font-weight: 700;
+  letter-spacing: -0.01em;
+  font-variant-numeric: tabular-nums;
+  cursor: pointer;
+  transition: border-color 0.14s ease, background-color 0.14s ease;
+}
+
+.headLabel:hover:not(:disabled) {
+  border-color: var(--thorp-line-control);
+  background: var(--thorp-surface);
+}
+
+/* 해 판이 맨 위층이라 더 올라갈 곳이 없다. 흐리게 만들지 않고 누를 수만 없게 둔다. */
+.headLabel:disabled {
+  cursor: default;
+}
+
+.headLabel:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.nav {
+  display: inline-grid;
+  place-items: center;
+  width: 26px;
+  height: 26px;
+  padding: 0;
+  border: 1px solid var(--thorp-line-control);
+  border-radius: 8px;
+  background: transparent;
+  color: inherit;
+  cursor: pointer;
+  transition: border-color 0.14s ease, background-color 0.14s ease;
+}
+
+.nav:hover:not(:disabled) {
+  border-color: var(--thorp-line-control-hover);
+  background: var(--thorp-surface);
+}
+
+.nav:disabled {
+  opacity: 0.35;
+  cursor: not-allowed;
+}
+
+.nav:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.weekdays,
+.grid {
+  display: grid;
+  grid-template-columns: repeat(7, 1fr);
+  gap: 2px;
+}
+
+.weekdays {
+  margin-bottom: 4px;
+}
+
+.weekday {
+  padding: 4px 0;
+  color: var(--thorp-muted);
+  font-size: 0.7rem;
+  font-weight: 600;
+  text-align: center;
+}
+
+/* 토·일은 글자색만 달리한다. 칸 배경까지 물들이면 고른 날이 묻힌다. */
+.weekday[data-weekend='sun'],
+.day[data-weekend='sun'] {
+  color: #e59a9a;
+}
+
+.weekday[data-weekend='sat'],
+.day[data-weekend='sat'] {
+  color: #8fb6e5;
+}
+
+.day {
+  padding: 6px 0;
+  border: 1px solid transparent;
+  border-radius: 8px;
+  background: transparent;
+  color: var(--thorp-foreground);
+  font: inherit;
+  font-size: 0.82rem;
+  font-variant-numeric: tabular-nums;
+  cursor: pointer;
+  transition: background-color 0.12s ease, border-color 0.12s ease;
+}
+
+.day:hover:not(:disabled) {
+  background: var(--thorp-surface);
+}
+
+/* 이웃 달의 날이다. 줄 맞추기용이라 흐리게 두되 고를 수는 있다. */
+.day[data-outside='true'] {
+  color: var(--thorp-muted);
+}
+
+/* 오늘은 테두리로만 알린다. 고른 날과 겹쳐도 서로를 가리지 않는다. */
+.day[data-today='true'] {
+  border-color: var(--thorp-line-control);
+}
+
+.day[data-selected='true'] {
+  border-color: var(--thorp-accent);
+  background: var(--thorp-accent);
+  color: var(--thorp-action-foreground);
+  font-weight: 700;
+}
+
+/*
+  못 고르는 날이다. 숫자를 거의 지워 눌러 볼 생각이 들지 않게 한다 — 시작일보다 앞선 날,
+  종료일보다 뒤인 날, 자료가 없는 구간이 모두 여기 걸린다. 잘못된 기간을 만들 수 없으니
+  그에 대한 오류 문장도 읽을 일이 없다.
+*/
+.day:disabled {
+  opacity: 0.16;
+  cursor: not-allowed;
+}
+
+.day:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+/* 달 판은 3×4, 해 판은 3×3이다. 칸 생김새(.month)는 둘이 함께 쓴다. */
+.months,
+.years {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 6px;
+}
+
+.month {
+  padding: 9px 0;
+  border: 1px solid transparent;
+  border-radius: 8px;
+  background: transparent;
+  color: var(--thorp-foreground);
+  font: inherit;
+  font-size: 0.84rem;
+  cursor: pointer;
+  transition: background-color 0.12s ease, border-color 0.12s ease;
+}
+
+.month:hover:not(:disabled) {
+  background: var(--thorp-surface);
+}
+
+.month[data-selected='true'] {
+  border-color: var(--thorp-accent);
+  background: var(--thorp-accent);
+  color: var(--thorp-action-foreground);
+  font-weight: 700;
+}
+
+.month:disabled {
+  opacity: 0.16;
+  cursor: not-allowed;
+}
+
+.month:focus-visible {
+  outline: var(--thorp-focus-outline-compact);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+/* 판 아래 줄. 오늘로 보내기와 비우기가 놓인다. */
+.foot {
+  display: flex;
+  justify-content: space-between;
+  gap: 8px;
+  margin-top: 10px;
+  padding-top: 10px;
+  border-top: 1px solid var(--thorp-line);
+}
+
+.footButton {
+  padding: 5px 11px;
+  border: 1px solid var(--thorp-line-control);
+  border-radius: 999px;
+  background: transparent;
+  color: var(--thorp-copy);
+  font: inherit;
+  font-size: 0.76rem;
+  cursor: pointer;
+  transition: border-color 0.14s ease, color 0.14s ease;
+}
+
+.footButton:hover:not(:disabled) {
+  border-color: var(--thorp-line-control-hover);
+  color: var(--thorp-foreground);
+}
+
+.footButton:disabled {
+  opacity: 0.35;
+  cursor: not-allowed;
+}
+
+.footButton:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .trigger,
+  .nav,
+  .day,
+  .month,
+  .footButton {
+    transition: none;
+  }
+}

